target.css:
:root {
  --ink: #28213a;
  --paper: #fffdf8;
  --line: #d9d1e6;
  --lavender: #eee9fa;
  --violet: #7655b8;
  --coral: #e96f62;
  --mint: #77bfa3;
  --disc: #45315f;
  --label: #f5c84b;
}

.press-card {
  box-sizing: border-box;
  width: 488px;
  padding: 14px;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 18px;
}

.press-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--violet);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}

.press-header h1 {
  margin: 0;
  font-size: 21px;
  font-weight: 800;
  letter-spacing: -0.035em;
  line-height: 1.05;
}

.run-id {
  padding: 5px 8px;
  color: var(--paper);
  background: var(--ink);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  line-height: 1;
}

.run-grid {
  display: grid;
  grid-template-columns: 112px 1fr;
  gap: 10px;
  margin-top: 11px;
}

.disc-panel {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 96px;
  margin: 0;
  background: var(--lavender);
  border: 1px solid var(--line);
  border-radius: 12px 12px 28px 12px;
}

.disc {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 76px;
  height: 76px;
  background: var(--disc);
  border: 4px solid var(--violet);
  border-radius: 50%;
}

.ring {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 43px;
  height: 43px;
  border: 2px solid var(--lavender);
  border-radius: 50%;
}

.label {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 21px;
  height: 21px;
  color: var(--ink);
  background: var(--label);
  border-radius: 50%;
  font-size: 9px;
  font-weight: 900;
}

.run-details {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.status-line {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 0 0 4px;
  color: var(--violet);
  font-size: 11px;
  font-weight: 800;
  line-height: 1.1;
}

.status-dot {
  width: 8px;
  height: 8px;
  background: var(--mint);
  border: 1px solid var(--ink);
  border-radius: 50%;
}

.run-details h2 {
  margin: 0 0 9px;
  font-size: 16px;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 5px;
}

.metric {
  margin: 0;
  padding: 6px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 7px;
}

.metric span {
  display: block;
  margin-bottom: 2px;
  color: var(--violet);
  font-size: 9px;
  font-weight: 800;
  line-height: 1;
  text-transform: uppercase;
}

.metric strong {
  display: block;
  font-size: 11px;
  font-weight: 800;
  line-height: 1.1;
  white-space: nowrap;
}

.stage-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 9px;
  padding: 8px 9px;
  background: var(--ink);
  border-radius: 10px;
}

.stage-title {
  margin: 0;
  color: var(--label);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.05em;
  line-height: 1;
  text-transform: uppercase;
}

.stage-list {
  display: grid;
  grid-template-columns: repeat(3, auto);
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.stage-list li {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--lavender);
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
}

.stage-dot {
  width: 7px;
  height: 7px;
  background: var(--coral);
  border-radius: 50%;
}

.stage-list li.current {
  color: var(--paper);
}

.stage-list li.current .stage-dot {
  background: var(--mint);
}

.press-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 9px;
}

.press-footer p {
  margin: 0;
  color: var(--violet);
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
}

.release-button {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--coral);
  border: 1px solid var(--ink);
  border-radius: 7px;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
}

